return ['domain'=>'tag-groups','plural-forms'=>'nplurals=3; plural=(n==1) ? 0 : (n>=2 && n<=4) ? 1 : 2;','language'=>'cs-CZ','project-id-version'=>'Tag Groups 2.1.2','pot-creation-date'=>'2026-06-15T12:41:40+00:00','po-revision-date'=>'2026-06-15 13:16+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['Tag Groups'=>'Tag-Groups','https://wordpress.org/plugins/tag-groups/'=>'https://wordpress.org/plugins/tag-groups/','Tag Groups allows you to organize your WordPress taxonomy terms and show them in clouds, tabs, accordions, tables, lists and much more.'=>'Tag-Groups umožňuje organizovat vaše termíny taxonomie WordPress a zobrazit je v oblacích, záložkách, akordeonech, tabulkách, seznamu a mnohem více.','TaxoPress'=>'TaxoPress','https://taxopress.com'=>'https://taxopress.com','Home'=>'Domů','Taxonomies'=>'Taxonomie','Front End'=>'Přední část','Back End'=>'Zadní část','First Steps'=>'První kroky','Setup Wizard'=>'Průvodce nastavením','Settings'=>'Nastavení','Tag Group Admin'=>'Admin skupin tagů','The term has been removed from all groups.'=>'Termín byl odstraněn ze všech skupin.','Edit this item inline'=>'Upravit tuto položku inline','Quick&nbsp;Edit'=>'Rychlá úprava','Please <a %s>click here to run the migration routines</a> to make sure we have migrated all tags.'=>'Prosím <a %s>klikněte zde pro spuštění migračních rutin</a> abyste se ujistili, že jsme migrovali všechny tagy.','Your settings/groups and your terms have been exported. Please download the resulting files with right-click or ctrl-click:'=>'Vaše nastavení/skupiny a vaše termíny byly exportovány. Prosím, stáhněte si výsledné soubory pravým kliknutím nebo ctrl-kliknutím:','Writing of the exported settings failed.'=>'Zápis exportovaných nastavení se nezdařil.','The groups have been sorted alphabetically.'=>'Skupiny byly seřazeny abecedně.','The label cannot be empty.'=>'Štítek nemůže být prázdný.','A tag group with the label \'%s\' already exists, or the label has not changed. Please choose another one or go back.'=>'Skupina štítků se štítkem \'%s\' již existuje, nebo se štítek nezměnil. Prosím vyberte jiný nebo se vraťte.','A new tag group with the label \'%s\' has been created!'=>'Byla vytvořena nová skupina štítků se štítkem \'%s\'!','A tag group with the label \'%s\' already exists.'=>'Skupina štítků se štítkem \'%s\' již existuje.','The tag group with the label \'%s\' has been saved!'=>'Skupina štítků se štítkem \'%s\' byla uložena!','A tag group with the id %1$s and the label \'%2$s\' has been deleted.'=>'Skupina štítků s ID %1$s a štítkem \'%2$s\' byla smazána.','Error uploading the file.'=>'Chyba při nahrávání souboru.','Error reading the file.'=>'Chyba při čtení souboru.','Error parsing the file.'=>'Chyba při parsování souboru.','date unknown'=>'datum neznámé','Your settings and groups have been imported from the file %1$s (created with plugin version %2$s on %3$s).'=>'Vaše nastavení a skupiny byly importovány ze souboru %1$s (vytvořeno s verzí pluginu %2$s dne %3$s).','%d option was added or changed.'=>'%d volba byla přidána nebo změněna.' . "\0" . '%d možnosti byly přidány nebo změněny.','Your terms have been imported from the file %1$s (created with plugin version %2$s on %3$s).'=>'Vaše termíny byly importovány ze souboru %1$s (vytvořeno s verzí pluginu %2$s dne %3$s).','We processed %d term.'=>'Zpracovali jsme %d termín.' . "\0" . 'Zpracovali jsme %d termíny.','We saved %d term.'=>'Uložili jsme %d termín.' . "\0" . 'Uložili jsme %d termíny.','The group info of %d term was updated.'=>'Informace o skupině %d termínu byly aktualizovány.' . "\0" . 'Informace o skupině %d termínů byly aktualizovány.','Filters'=>'Filtry','Gutenberg'=>'Gutenberg','Multilingual'=>'Vícejazyčný','Shortcodes'=>'Krátké kódy','Themes and Appearance'=>'Témata a vzhled','remove'=>'odstranit','(recommended)'=>'(doporučeno)','keep'=>'uchovat','use unfiltered_html filter'=>'použít filtr unfiltered_html','First Aid'=>'První pomoc','REST API'=>'REST API','System Information'=>'Informace o systému','Debugging'=>'Ladění','Export/Import'=>'Export/Import','Reset'=>'Obnovit','Licences'=>'Licence','Transients'=>'Dočasné','Database'=>'Databáze','Filesystem'=>'Souborový systém','WP Object Cache'=>'WP Object Cache','Your settings have been saved.'=>'Vaše nastavení byla uložena.','Your settings has been saved.'=>'Vaše nastavení bylo uloženo.','All groups have been deleted and assignments reset.'=>'Všechny skupiny byly smazány a přiřazení obnoveno.','The filter on the tags page has been reset to show all tags.'=>'Filtr na stránce štítků byl obnoven, aby zobrazoval všechny štítky.','tag groups'=>'skupiny tagů','tag cloud'=>'tagová cloud','group info'=>'informace o skupině','sidebar widget'=>'widget bočního panelu','accordion'=>'akordeon','tabs'=>'karty','alphabetical'=>'abecední','post list'=>'seznam příspěvků','colors'=>'barvy','tag description'=>'popis tagu','tag filter'=>'filtr tagů','post filter'=>'filtr příspěvků','backup'=>'záloha','remove plugin'=>'odebrat plugin','remove data'=>'odebrat data','delete groups'=>'smazat skupiny','debugging'=>'ladění','PHP Version'=>'verze PHP','Ajax Test'=>'Ajax test','troubleshooting'=>'odstraňování problémů','benchmarks'=>'benchmarky','speed test'=>'test rychlosti','error'=>'chyba','testing'=>'testování','help'=>'nápověda','Tag Groups Pro'=>'Tag Groups Pro','upgrade'=>'aktualizace','more groups'=>'více skupin','posts'=>'příspěvky','filter'=>'filtr','animated'=>'animovaný','searchable'=>'hledatelný','Info'=>'Info','author'=>'autor','version'=>'verze','contact'=>'kontakt','about'=>'o aplikaci','Licenses'=>'Licence','Credits'=>'Zásluhy','Development News'=>'Novinky ve vývoji','blog'=>'blog','updates'=>'aktualizace','getting started'=>'začínáme','introduction'=>'úvod','sample'=>'ukázka','migrate'=>'migrovat','problem'=>'problém','live block preview'=>'náhled živého bloku','translation'=>'překlad','Migrating the term meta'=>'Migrace termínu meta','Fixing incorrect tag groups'=>'Oprava nesprávných skupin štítků','Fixing incorrect groups in term meta'=>'Oprava nesprávných skupin v termínu meta','Sorting groups in term meta'=>'Třídění skupin v termínu meta','Checking the tag names'=>'Kontrola názvů štítků','Start'=>'Začít','Sample Content'=>'Ukázkový obsah','Sample Group A'=>'Ukázková skupina A','Sample Group B'=>'Ukázková skupina B','Sample Group C'=>'Ukázková skupina C','First Sample Tag'=>'První ukázkový štítek','Second Sample Tag'=>'Druhý ukázkový tag','Third Sample Tag'=>'Třetí ukázkový tag','Create a draft sample page with Gutenberg blocks.'=>'Vytvořte koncept ukázkové stránky s bloky Gutenberg.','Create a draft sample page with shortcodes.'=>'Vytvořte koncept ukázkové stránky s krátkými kódy.','The plugin %1$s requires WordPress %2$s to function properly.'=>'Plugin %1$s vyžaduje WordPress %2$s k správnému fungování.','Please upgrade WordPress and then try again.'=>'Prosím, aktualizujte WordPress a zkuste to znovu.','not assigned'=>'není přiřazeno','You\'re using Tag Groups Free. The Pro version has more features and support. %sUpgrade to Pro%s'=>'Používáte Tag Groups Free. Pro verze má více funkcí a podporu. %sPřechod na Pro%s','Upgrade to Pro'=>'Přechod na Pro','Upgrade to Tag Groups Pro'=>'Přechod na Tag Groups Pro','Enhance the power of Tag Groups with the Pro version:'=>'Zvyšte sílu Tag Groups s Pro verzí:','21 Shortcodes'=>'21 Krátkých kódů','18 Gutenberg Blocks'=>'18 Bloků Gutenberg','Table Tag Cloud'=>'Tag Cloud Tabulka','Simple Tag Cloud'=>'Jednoduchý Tag Cloud','Shuffle Box'=>'Shuffle Box','Caching'=>'Caching','Multiple Groups Per Tag'=>'Více skupin na tag','Tag Cloud Search'=>'Vyhledávání v Tag Cloud','Toggle Post Filter'=>'Přepnout filtr příspěvků','Dynamic Post Filter'=>'Dynamický filtr příspěvků','Post List'=>'Seznam příspěvků','Tag Meta Box'=>'Meta box pro štítky','Post Tags in Groups'=>'Štítky příspěvků ve skupinách','Permissions'=>'Oprávnění','Default Groups'=>'Výchozí skupiny','WooCommerce Attributes'=>'Atributy WooCommerce','Parent Group Level'=>'Úroveň nadřazené skupiny','Need Tag Groups Support?'=>'Potřebujete podporu pro skupiny štítků?','If you need help or have a new feature request, let us know.'=>'Pokud potřebujete pomoc nebo máte žádost o novou funkci, dejte nám vědět.','Request Support'=>'Požádat o podporu','Detailed documentation is also available on the plugin website.'=>'Podrobné dokumentace je také k dispozici na webových stránkách pluginu.','View Knowledge Base'=>'Zobrazit znalostní bázi','The free Tag Groups plugin cannot be active together with Tag Groups Pro.'=>'Bezplatný plugin pro skupiny štítků nemůže být aktivní společně se skupinami štítků Pro.','more information'=>'více informací','Edit tag groups'=>'Upravit skupiny štítků','Clicking will leave this page without saving.'=>'Kliknutím opustíte tuto stránku bez uložení.','Welcome to %s!'=>'Vítejte ve %s!','The plugin is ready for use. If you need some assistance, we can walk you through the basic steps.'=>'Plugin je připraven k použití. Pokud potřebujete pomoc, můžeme vás provést základními kroky.','Start the Setup Wizard'=>'Spustit průvodce nastavením','Or click here if you prefer to do it on your own.'=>'Nebo klikněte sem, pokud dáváte přednost dělat to sami.','Go to the <span class="dashicons dashicons-tag"></span>&nbsp;Tag Groups <a %s>taxonomy settings</a> and <b>select the taxonomy</b> (tag type) of your tags. In most cases just leave the default: Tags (post_tag).'=>'Přejděte na <span class="dashicons dashicons-tag"></span>&nbsp;Nastavení skupin tagů <a %s>taxonomy settings</a> a <b>vyberte taxonomy</b> (typ tagu) svých tagů. Ve většině případů stačí ponechat výchozí: Tagy (post_tag).','Go to the tag groups admin page and <b>create some groups</b>.'=>'Přejděte na administrační stránku skupin tagů a <b>vytvořte nějaké skupiny</b>.','You can find these pages listed on your <a %s>Tag Groups home page</a>.'=>'Tyto stránky najdete uvedené na vaší <a %s>domovské stránce skupin tagů</a>.','Go to your tags and <b>assign them to these groups</b>.'=>'Přejděte na své tagy a <b>přiřaďte je těmto skupinám</b>.','Filter by tag group'=>'Filtr podle skupiny tagů','%s created this sample page in the Setup Wizard of the <b>Tag Groups</b> plugin. You can safely edit and delete it or keep it for future reference.'=>'%s vytvořil tuto ukázkovou stránku v Průvodci nastavením pluginu <b>Tag Groups</b>. Můžete ji bezpečně upravit a smazat nebo si ji ponechat pro budoucí použití.','The following shortcodes use a variety of parameters so that you can get an idea of the options. Feel free to generate a new sample page with more features after upgrading the plugin.'=>'Následující krátké kódy používají různé parametry, abyste si mohli udělat představu o možnostech. Po upgradu pluginu se nebojte vygenerovat novou vzorovou stránku s více funkcemi.','Please find links to the documentation in the <a %s>Tag Groups settings</a>.'=>'Najděte prosím odkazy na dokumentaci v <a %s>nastavení skupin tagů</a>.','Tabbed Tag Cloud'=>'Záložkový tag cloud','Accordion Tag Cloud'=>'Akkordeonový tag cloud','Alphabetical Tag Cloud'=>'Abecední tag cloud','Tag List'=>'Seznam tagů','Alphabetical Tag Index'=>'Abecední index tagů','The following blocks use a variety of parameters so that you can get an idea of the options. Feel free to generate a new sample page with more features after upgrading the plugin.'=>'Následující bloky používají různé parametry, abyste si mohli udělat představu o možnostech. Po upgradu pluginu se nebojte vygenerovat novou vzorovou stránku s více funkcemi.','This page was created while you had the Gutenberg editor enabled. Therefore the features only display while Gutenberg is active.'=>'Tato stránka byla vytvořena, když jste měli povolený editor Gutenberg. Proto se funkce zobrazují pouze, když je Gutenberg aktivní.','Display filter on the "Posts" screen.'=>'Zobrazit filtr na obrazovce "Příspěvky".','Add a pull-down menu to the filters above the list of posts. If you filter posts by tag groups, then only items will be shown that have tags (terms) in that particular group. This feature can be turned off so that the menu won\'t obstruct your screen if you use a high number of groups. May not work with all taxonomies.'=>'Přidejte rozbalovací menu k filtrům nad seznamem příspěvků. Pokud filtrujete příspěvky podle skupin tagů, budou zobrazeny pouze položky, které mají tagy (termíny) v té konkrétní skupině. Tuto funkci lze vypnout, aby menu nebránilo vaší obrazovce, pokud používáte velký počet skupin. Nemusí fungovat se všemi taxonomií.','Display filter on the "Tags" screen.'=>'Zobrazit filtr na obrazovce "Tagy".','Add a filter to the list of tags. Disable it here if it conflicts with other plugins or themes.'=>'Přidejte filtr do seznamu tagů. Zde jej deaktivujte, pokud koliduje s jinými pluginy nebo motivy.','Save Settings'=>'Uložit nastavení','Gutenberg block preview'=>'Náhled bloku Gutenberg','Some blocks can show an approximate preview in the Gutenberg editor. If you deactivate this option, then all blocks will show a static icon with text.'=>'Některé bloky mohou zobrazit přibližný náhled v editoru Gutenberg. Pokud tuto možnost deaktivujete, všechny bloky zobrazí statickou ikonu s textem.','Keep groups of translations in sync'=>'Udržovat skupiny překladů synchronizované','If you activate this option, we try to sync the groups across all language versions of a tag when you save it. Deactivate it to set groups independently.'=>'Pokud aktivujete tuto možnost, pokusíme se synchronizovat skupiny napříč všemi jazykovými verzemi štítku, když ho uložíte. Deaktivujte to, abyste nastavili skupiny nezávisle.','All Tag Groups features are available as Gutenberg blocks. You can also use shortcodes.'=>'Všechny funkce Tag Groups jsou k dispozici jako bloky Gutenberg. Můžete také použít shortcodes.','Click on the features for more information.'=>'Klikněte na funkce pro více informací.','Display the tags in a tabbed tag cloud.'=>'Zobrazit štítky v kartovém mraku štítků.','Example'=>'Příklad','Parameters'=>'Parametry','Please find the parameters in the <a %s>documentation</a>.'=>'Najděte prosím parametry v <a %s>dokumentaci</a>.','Accordion'=>'Akordeon','Display the tags in an accordion.'=>'Zobrazit štítky v akordeonu.','Display the tags in lists under tag groups.'=>'Zobrazit štítky v seznamech pod skupinami štítků.','Display the tags in tabbed tag cloud with first letters as tabs.'=>'Zobrazit štítky v kartovém mraku štítků s prvními písmeny jako kartami.','(Not tested with right-to-left languages.)'=>'(Nebylo testováno s jazyky píšícími zprava doleva.)','Display the tags in a list with first letters as heading.'=>'Zobrazit štítky v seznamu s prvními písmeny jako nadpisem.','Group Information'=>'Informace o skupině','Display information about tag groups.'=>'Zobrazit informace o skupinách štítků.','The function <b>tag_groups_cloud</b> accepts the same parameters as the [tag_groups_cloud] shortcode, except for those that determine tabs and styling.'=>'Funkce <b>tag_groups_cloud</b> přijímá stejné parametry jako shortcode [tag_groups_cloud], s výjimkou těch, které určují karty a stylování.','By default it returns a string with the html for a tabbed tag cloud.'=>'Ve výchozím nastavení vrací řetězec s HTML pro záložkový tag cloud.','If the optional second parameter is set to \'true\', the function returns a multidimensional array containing tag groups and tags.'=>'Pokud je volitelný druhý parametr nastaven na \'true\', funkce vrátí vícerozměrné pole obsahující skupiny tagů a tagy.','Enable shortcode in sidebar widgets (if not visible anyway).'=>'Povolit shortcode v postranních widgete (pokud není stejně viditelný).','Always load shortcode scripts.'=>'Vždy načíst skripty shortcode.','Click for more information'=>'Klikněte pro více informací','Turn off to load the scripts only on posts and pages where a shortcode appears.'=>'Vypněte, abyste načítali skripty pouze na příspěvcích a stránkách, kde se shortcode objevuje.','Turn on if you use these shortcodes in widgets.'=>'Zapněte, pokud používáte tyto shortcody ve widgete.','Here you can choose a theme for the Tabbed Tag Cloud and the Accordion Tag Cloud.'=>'Zde si můžete vybrat téma pro záložkový tag cloud a akordeonový tag cloud.','New themes can be created with the <a href="http://jqueryui.com/themeroller/" target="_blank">jQuery UI ThemeRoller</a>:'=>'Nová témata lze vytvořit pomocí <a href="http://jqueryui.com/themeroller/" target="_blank">jQuery UI ThemeRoller</a>:','On the page "Theme Roller" you can customize all features or pick one set from the gallery. Finish with the "download" button.'=>'Na stránce "Theme Roller" si můžete přizpůsobit všechny funkce nebo vybrat jednu sadu z galerie. Dokončete to stisknutím tlačítka "stáhnout".','On the next page ("Download Builder") you will need to select the version 1.12.x and the components "Widget", "Accordion" and "Tabs". Make sure that before downloading you enter at the bottom as "CSS Scope" <b>.tag-groups-cloud</b> (including the dot).'=>'Na další stránce ("Download Builder") budete muset vybrat verzi 1.12.x a komponenty "Widget", "Accordion" a "Tabs". Ujistěte se, že před stažením zadáte na dně jako "CSS Scope" <b>.tag-groups-cloud</b> (včetně tečky).','Then you unpack the downloaded zip file. You will need the "images" folder and the "jquery-ui.theme.min.css" file.'=>'Poté rozbalíte stažený zip soubor. Budete potřebovat složku "images" a soubor "jquery-ui.theme.min.css".','Create a new folder inside your <i>wp-content/uploads</i> folder (for example "my-theme") and copy there these two items.'=>'Vytvořte novou složku uvnitř vaší <i>wp-content/uploads</i> složky (například "my-theme") a zkopírujte tam tyto dvě položky.','Enter the name of this new folder (for example "my-theme") below.'=>'Zadejte název této nové složky (například "my-theme") níže.','own theme'=>'vlastní téma','Don\'t load a theme.'=>'Nenačítat téma.','Here you can turn off jQuery UI themes if your WordPress theme brings its own jQuery UI theme, in order to avoid conflicts.'=>'Zde můžete vypnout jQuery UI témata, pokud váš WordPress téma přináší své vlastní jQuery UI téma, abyste se vyhnuli konfliktům.','Further options'=>'Další možnosti','Use jQuery.  (Default is on. Other plugins might override this setting.)'=>'Použít jQuery. (Výchozí je zapnuto. Jiné pluginy mohou přepsat toto nastavení.)','Tabs triggered by hovering mouse pointer (without clicking).'=>'Záložky vyvolané pohybem ukazatele myši (bez kliknutí).','Collapsible tabs (toggle open/close).'=>'Skrývací karty (přepnout otevřít/zavřít).','HTML in tag description:'=>'HTML v popisu tagu:','By default the description appears in a tooltip when you hover the mouse over a tag in a tag cloud.'=>'Ve výchozím nastavení se popis zobrazuje v nápovědě, když najedete myší na tag v tagovém cloudu.','If you don\'t trust all users of your site, remove the HTML or use a plugin to give the unfiltered_html capability only to users you trust.'=>'Pokud nedůvěřujete všem uživatelům vaší stránky, odstraňte HTML nebo použijte plugin, který poskytne schopnost unfiltered_html pouze uživatelům, kterým důvěřujete.','Save Theme Options'=>'Uložit možnosti motivu','Search for settings'=>'Hledat nastavení','Search for setting pages. Type a space to show all settings.'=>'Hledat stránky nastavení. Zadejte mezeru pro zobrazení všech nastavení.','Search Results'=>'Výsledky hledání','Nothing found'=>'Nenašlo se nic','Active Taxonomies'=>'Aktivní taxonomie','Group Statistics'=>'Statistika skupiny','for the selected language'=>'pro vybraný jazyk','go to tag group administration'=>'přejít do správy skupin tagů','Enable Tag Groups Public API Access'=>'Povolit veřejný přístup k API Tag Groups','Enable public access to tag groups endpoint /wp-json/tag-groups/v1/groups/.'=>'Povolit veřejný přístup k koncovému bodu skupin tagů /wp-json/tag-groups/v1/groups/.','Enable Terms Public API Access'=>'Povolit veřejný přístup k API Terms','Enable public access to terms endpoint /wp-json/tag-groups/v1/terms/.'=>'Povolit veřejný přístup k koncovému bodu termínů /wp-json/tag-groups/v1/terms/.','Choose the taxonomies for which you want to use Tag Groups:'=>'Vyberte taxonomie, pro které chcete používat Tag-Groups:','The default texonomy is <b>Tags (post_tag)</b>. Please note that the tag clouds might not work with all taxonomies and that some taxonomies listed here may not be accessible in the admin backend. If you don\'t understand what is going on here, just leave the default.'=>'Výchozí taxonomie je <b>Tags (post_tag)</b>. Vezměte prosím na vědomí, že tagové cloudu nemusí fungovat se všemi taxonomiemi a že některé taxonomie uvedené zde nemusí být přístupné v administraci. Pokud nerozumíte, co se zde děje, jednoduše nechte výchozí nastavení.','<b>Please deselect taxonomies that you don\'t use. Using several taxonomies for the same post type or hierarchical taxonomies (like categories) is experimental and not supported.</b>'=>'<b>Prosím, zrušte výběr taxonomií, které nepoužíváte. Používání několika taxonomií pro stejný typ příspěvku nebo hierarchických taxonomií (jako kategorie) je experimentální a není podporováno.</b>','To see the post type, hover your mouse over the option.'=>'Chcete-li vidět post type, přesuňte myš nad možnost.','If you use a custom taxonomy, make sure that the attribute "Public" is set to "true" and "Hierarchical" to "false".'=>'Pokud používáte vlastní taxonomy, ujistěte se, že je atribut "Public" nastaven na "true" a "Hierarchical" na "false".','Show hierarchical taxonomies. Not all Tag Groups features will work with these taxonomies.'=>'Zobrazit hierarchické taxonomies. Ne všechny funkce Tag Groups budou fungovat s těmito taxonomies.','Save Taxonomies'=>'Uložit Taxonomies','Export'=>'Exportovat','Use this button to export all Tag Groups settings and groups and all terms that are assigned to a group into files.'=>'Použijte toto tlačítko k exportu všech nastavení a skupin Tag Groups a všech termínů, které jsou přiřazeny ke skupině, do souborů.','You can import both files separately. Category hierarchy won\'t be saved. When you restore terms that were deleted, they receive new IDs and you must assign them to posts again. Exporting cannot substitute a backup.'=>'Můžete importovat oba soubory samostatně. Hierarchie kategorií nebude uložena. Když obnovíte termíny, které byly smazány, obdrží nové ID a musíte je znovu přiřadit k příspěvkům. Exportování nemůže nahradit zálohu.','Export Files'=>'Exportovat Soubory','Import'=>'Importovat','Below you can import previously exported settings/groups or terms from a file.'=>'Níže můžete importovat dříve exportovaná nastavení/skupiny nebo termíny ze souboru.','It is recommended to back up the database of your site before proceeding.'=>'Doporučuje se zálohovat databázi vašeho webu před pokračováním.','Please import the settings before the terms.'=>'Prosím, importujte nastavení před termíny.','Import File'=>'Importovat Soubory','Use this button to delete all tag groups and assignments. Your tags will not be changed. Check the checkbox to confirm.'=>'Použijte toto tlačítko k odstranění všech skupin tagů a přiřazení. Vaše tagy nebudou změněny. Zaškrtněte políčko pro potvrzení.','Please keep in mind that the tag assignments cannot be recovered by the export/import function.'=>'Mějte prosím na paměti, že přiřazení tagů nelze obnovit pomocí funkce exportu/importu.','I know what I am doing.'=>'Vím, co dělám.','Delete Groups'=>'Smazat Skupiny','Delete Settings and Groups'=>'Smazat Nastavení a Skupiny','Delete all groups and settings when uninstalling the plugin.'=>'Smazat všechny skupiny a nastavení při odinstalaci pluginu.','Debug mode is on.'=>'Režim ladění je zapnutý.','Verbose logging is enabled with CM_DEBUG.'=>'Verbose logging je povolen s CM_DEBUG.','Verbose logging is on.'=>'Verbose logging je zapnutý.','Turn off '=>'Vypnout ','Verbose logging is off.'=>'Verbose logging je vypnutý.','Turn on'=>'Zapnout','Debug mode is off.'=>'Debugovací režim je vypnutý.','Learn more <a %s>about debugging</a>.'=>'Zjistit více <a %s>o ladění</a>.','Migrate tags to the new format of Tag Groups.'=>'Migrace tagů na nový formát skupin tagů.','The plugin automatically migrates tags to the new format and tries to keep track of changes. There may, however, be cases where other components made unnoticed changes. You might also need to manually migrate tags after you enabled a taxonomy that already contained untracked tags.'=>'Plugin automaticky migruje tagy na nový formát a snaží se sledovat změny. Může však dojít k případům, kdy jiné komponenty provedly nezpozorované změny. Možná budete muset také ručně migrovat tagy poté, co jste povolili taxonomii, která již obsahovala nesledované tagy.','Migrate'=>'Migrace','Running the maintenance can solve issues that you encounter during filtering by tag groups.'=>'Spuštění údržby může vyřešit problémy, které se vyskytnou během filtrování podle skupin tagů.','Maintenance'=>'Údržba','Reset the filter on the tags page to show all tags.'=>'Resetujte filtr na stránce tagů, abyste zobrazili všechny tagy.','Use it if a JavaScript error disables the filter menu. Note that it is still recommended to find out the cause of the error.'=>'Použijte to, pokud JavaScriptová chyba deaktivuje nabídku filtrů. Všimněte si, že je stále doporučeno zjistit příčinu chyby.','Reset Tag Filter'=>'Resetovat filtr tagů','Please stay on this page until all processes have finished.'=>'Prosím, zůstaňte na této stránce, dokud všechny procesy neskončí.','There have been errors.'=>'Došlo k chybám.','Continue'=>'Pokračovat','Finished!'=>'Hotovo!','The following terms cannot be used:'=>'Následující termíny nelze použít:','Number of processed items: '=>'Počet zpracovaných položek: ','Number of changed items: '=>'Počet změněných položek: ','WordPress Version'=>'WordPress Verze','Site URL'=>'URL webu','Home URL'=>'URL domovské stránky','Active Theme'=>'Aktivní téma','Version'=>'Verze','Checking...'=>'Kontroluji...','Show the Response'=>'Zobrazit odpověď','passed'=>'úspěšně','failed'=>'neúspěšně','Benchmarks'=>'Měření výkonu','Cache'=>'Mezipaměť','Tag groups pro only'=>'Skupiny tagů pro pouze','Server'=>'Server','Constants'=>'Konstanty','Well done!'=>'Dobrá práce!','Now go the Tag Group Administration.'=>'Nyní přejděte na administraci skupin tagů.','Or preview the sample page here.'=>'Nebo si zde prohlédněte ukázkovou stránku.','Or go to the <a %s>Tag Groups settings</a> or visit the <a %s>documentation</a>.'=>'Nebo přejděte do <a %s>nastavení skupin tagů</a> nebo navštivte <a %s>dokumentaci</a>.','Now go to the <a %s>Tag Groups settings</a>, or visit the <a %s>documentation</a>.'=>'Nyní přejděte do <a %s>nastavení skupin štítků</a>, nebo navštivte <a %s>dokumentaci</a>.','If you need to launch the Setup Wizard again, you can find it in the settings. Just enter "wizard" in the search field.'=>'Pokud potřebujete znovu spustit Průvodce nastavením, najdete ho v nastavení. Stačí zadat "wizard" do vyhledávacího pole.','Happy tagging!'=>'Šťastné štítkování!','Tag Groups Setup Wizard'=>'Průvodce nastavením skupin štítků','Now you are ready to create your own tag groups. If you prefer to start out from a sample, we will create for you three groups and three tags. You can play around with them, rename or delete them.'=>'Nyní jste připraveni vytvořit si vlastní skupiny štítků. Pokud dáváte přednost začít od vzorku, vytvoříme pro vás tři skupiny a tři štítky. Můžete si s nimi hrát, přejmenovávat je nebo je mazat.','Create sample groups:'=>'Vytvořit vzorové skupiny:','Create sample tags in these groups:'=>'Vytvořit vzorové štítky v těchto skupinách:','Next Step'=>'Další krok','On the following pages we will guide you through the basic settings that you need for the most common features.'=>'Na následujících stránkách vás provedeme základními nastaveními, která potřebujete pro nejběžnější funkce.','You can later make changes or fine-tune the details in the Tag Groups settings.'=>'Později můžete provést změny nebo doladit detaily v nastavení skupin štítků.','(show me the menu)'=>'(ukázat menu)','Feel free to abort the Setup Wizard any time and continue on your own path. You can also launch it again at a later time.'=>'Neváhejte kdykoli přerušit Průvodce nastavením a pokračovat vlastní cestou. Můžete ho také znovu spustit později.','The wizard will offer more options after upgrading to premium.'=>'Průvodce nabídne více možností po upgradu na prémiovou verzi.','Choose the taxonomies for which you want to use tag groups.'=>'Vyberte taxonomie, pro které chcete používat skupiny štítků.','In most cases the default taxonomy <b>Tags (post_tag)</b> will do the job.'=>'Ve většině případů udělá svou práci výchozí taxonomie <b>Tags (post_tag)</b>.','post type'=>'post type','You will find more options in the Tag Groups settings.'=>'V nastavení skupin štítků naleznete více možností.','Tag Group Administration'=>'Administrace skupin štítků','Filter by label'=>'Filtr podle štítku','Tag Group name'=>'Název skupiny štítků','Number of assigned tags'=>'Počet přiřazených štítků','Actions'=>'Akce','Change order'=>'Změnit pořadí','Group ID'=>'ID skupiny','Edit'=>'Upravit','Create'=>'Vytvořit','new'=>'nový','label'=>'štítek','Delete this group.'=>'Smazat tuto skupinu.','Create a new group below.'=>'Vytvořte novou skupinu níže.','Add New Tag Group'=>'Přidat novou skupinu štítků','move up'=>'přesunout nahoru','move down'=>'přesunout dolů','reload'=>'aktualizovat','next page'=>'další stránka','previous page'=>'předchozí stránka','go to page:'=>'přejít na stránku:','Show posts'=>'Zobrazit příspěvky','Show tags'=>'Zobrazit štítky','Do you really want to delete this tag group?'=>'Opravdu chcete smazat tuto skupinu štítků?','Please visit <a %s>%s</a>.'=>'Prosím navštivte <a %s>%s</a>.','Read more'=>'Přečtěte si více','Thanks for using Tag Groups | %1sTaxoPress.com%2s | Version %3s'=>'Děkujeme, že používáte Tag Groups | %1sTaxoPress.com%2s | Verze %3s','Assign to'=>'Přiřadit k','Filter off'=>'Filtr vypnut','Please select one of the languages above to see the correct tag groups!'=>'Prosím vyberte jednu z výše uvedených jazyků pro zobrazení správných skupin tagů!','Groups'=>'Skupiny','You\'re using Tag Groups Free. The Pro version has more features and support. %1$sUpgrade to Pro%2$s'=>'Používáte Tag Groups Free. Pro verze má více funkcí a podporu. %1$sPřejít na Pro%2$s','Or go to the <a %1$s>Tag Groups settings</a> or visit the <a %2$s>documentation</a>.'=>'Nebo přejděte na <a %1$s>nastavení skupin tagů</a> nebo navštivte <a %2$s>dokumentaci</a>.','Now go to the <a %1$s>Tag Groups settings</a>, or visit the <a %2$s>documentation</a>.'=>'Nyní přejděte na <a %1$s>nastavení skupin tagů</a>, nebo navštivte <a %2$s>dokumentaci</a>.','Please visit <a %1$s>%2$s</a>.'=>'Prosím navštivte <a %1$s>%2$s</a>.','Thanks for using Tag Groups | %1$sTaxoPress.com%2$s | Version %3$s'=>'Děkujeme, že používáte Tag Groups | %1$sTaxoPress.com%2$s | Verze %3$s']];